     1	#[cfg(not(mobile))]
     2	use crate::commands::begin_native_close;
     3	use crate::state::AppState;
     4	use mail_core::drafts::DraftCore;
     5	use mail_core::fixture_transition::FixtureTransition;
     6	use mail_core::gmail::provider::LiveGmailProvider;
     7	use mail_core::gmail::secrets::KeychainSecrets;
     8	use mail_core::gmail::sync::GmailCore;
     9	use std::sync::Arc;
    10	use tauri::{Emitter, Manager, RunEvent};
    11	
    12	/// Opens the fixture profile under `app_data_dir`: the synthetic core on its
    13	/// own files. A legacy `mail.db` in the same directory is never opened here;
    14	/// retiring it is the explicit, disclosed transition (`fixture_transition`).
    15	/// The profile lock and `local-drafts` live in the same directory, so a second
    16	/// writer is rejected.
    17	pub(crate) fn open_fixture_core(
    18	    app_data_dir: &std::path::Path,
    19	) -> Result<(GmailCore, std::path::PathBuf), Box<dyn std::error::Error>> {
    20	    let profile_dir = app_data_dir.join("fixture-profile");
    21	    let core = GmailCore::open_synthetic_profile(
    22	        &profile_dir,
    23	        mail_core::synthetic::WriteControls::from_env(),
    24	        Arc::new(mail_core::clock::SystemClock),
    25	    )?;
    26	    Ok((core, profile_dir))
    27	}
    28	
    29	pub(crate) fn run(builder: tauri::Builder<tauri::Wry>) {
    30	    let app = builder
    31	        .on_window_event(|window, event| {
    32	            #[cfg(not(mobile))]
    33	            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
    34	                api.prevent_close();
    35	                begin_native_close(window.app_handle());
    36	            }
    37	            #[cfg(mobile)]
    38	            let _ = (window, event);
    39	        })
    40	        .setup(|app| {
    41	            #[cfg(mobile)]
    42	            let mode = "fixture".to_owned();
    43	            #[cfg(not(mobile))]
    44	            let mode = match std::env::var_os("EMAIL_OS_MODE") {
    45	                Some(value) => value
    46	                    .into_string()
    47	                    .map_err(|_| "EMAIL_OS_MODE must be valid UTF-8")?,
    48	                None => "fixture".to_owned(),
    49	            };
    50	            let app_data_dir = app.path().app_data_dir()?;
    51	            let (core, profile_dir) = match mode.as_str() {
    52	                "fixture" => open_fixture_core(&app_data_dir)?,
    53	                "gmail" => {
    54	                    let profile_dir = app_data_dir.join("gmail-profile");
    55	                    let provider = LiveGmailProvider::from_env(Arc::new(KeychainSecrets::new()))?;
    56	                    let provider: Arc<dyn mail_core::gmail::types::GmailProvider> =
    57	                        Arc::new(provider);
    58	                    (GmailCore::open(&profile_dir, provider)?, profile_dir)
    59	                }
    60	                _ => return Err("EMAIL_OS_MODE must be fixture or gmail".into()),
    61	            };
    62	            let drafts = DraftCore::open(profile_dir.join("local-drafts"))?;
    63	            // The one-time retirement of a legacy fixture database; a no-op in
    64	            // Gmail mode and on a fresh fixture profile.
    65	            app.manage(Arc::new(if mode == "fixture" {
    66	                FixtureTransition::new(&profile_dir)
    67	            } else {
    68	                FixtureTransition::inactive()
    69	            }));
    70	
    71	            let handle = app.handle().clone();
    72	            app.manage(AppState::new(core, drafts, move || {
    73	                // Notifications are best-effort hints; the frontend refetches persisted state.
    74	                let _ = handle.emit("mailbox_changed", ());
    75	            }));
    76	            Ok(())
    77	        })
    78	        .build(tauri::generate_context!())
    79	        .expect("failed to build the email-os shell");
    80	
    81	    app.run(|app_handle, event| match event {
    82	        #[cfg(not(mobile))]
    83	        RunEvent::ExitRequested { api, .. } => {
    84	            let authorized = app_handle
    85	                .try_state::<AppState>()
    86	                .and_then(|state| {
    87	                    state
    88	                        .close_gate
    89	                        .lock()
    90	                        .ok()
    91	                        .map(|mut gate| gate.take_exit_authorization())
    92	                })
    93	                .unwrap_or(false);
    94	            if !authorized {
    95	                api.prevent_exit();
    96	                begin_native_close(app_handle);
    97	            }
    98	        }
    99	        #[cfg(not(mobile))]
   100	        RunEvent::Exit => {
   101	            if let Some(state) = app_handle.try_state::<AppState>() {
   102	                state.core.stop();
   103	            }
   104	        }
   105	        _ => {}
   106	    });
   107	}
   108	
   109	#[cfg(test)]
   110	mod tests {
   111	    use crate::setup::open_fixture_core;
   112	    use crate::test_support::{conv, LEGACY_MAIL_DB};
   113	    use mail_core::drafts::load_validated_reply_context;
   114	    use mail_core::drafts::types::DraftSource;
   115	    use mail_core::drafts::DraftCore;
   116	    use mail_core::fixture_transition::FixtureTransition;
   117	    use mail_core::gmail::types::MailMode;
   118	    use mail_core::testing::temp_profile;
   119	
   120	    #[test]
   121	    fn the_default_is_the_synthetic_core_and_a_legacy_mail_db_is_never_opened() {
   122	        let dir = temp_profile("synthetic-default");
   123	        let profile = dir.path().join("fixture-profile");
   124	        std::fs::create_dir_all(&profile).unwrap();
   125	        std::fs::write(profile.join("mail.db"), LEGACY_MAIL_DB).unwrap();
   126	        let (core, opened) = open_fixture_core(dir.path()).unwrap();
   127	        assert_eq!(core.account_status().unwrap().mode, MailMode::Fixture);
   128	        assert_eq!(opened, profile);
   129	        assert!(profile.join("synthetic-provider.db").exists());
   130	        assert!(profile.join("gmail.db").exists());
   131	        assert_eq!(
   132	            std::fs::read(profile.join("mail.db")).unwrap(),
   133	            LEGACY_MAIL_DB
   134	        );
   135	        assert!(!profile.join("mail.db-wal").exists() && !profile.join("mail.db-shm").exists());
   136	        // The fixture profile has a single writer.
   137	        assert!(matches!(
   138	            open_fixture_core(dir.path()),
   139	            Err(error) if error.to_string().contains("another writer")
   140	        ));
   141	        core.stop();
   142	    }
   143	
   144	    /// The real startup order: the synthetic core is open (new files), then the
   145	    /// disclosed transition retires the legacy database beside it. Drafts keep
   146	    /// their account and their conversation/message references.
   147	    #[test]
   148	    fn retiring_the_legacy_database_beside_a_live_core_keeps_drafts_and_the_core_working() {
   149	        let dir = temp_profile("synthetic-transition");
   150	        let profile = dir.path().join("fixture-profile");
   151	        std::fs::create_dir_all(&profile).unwrap();
   152	        std::fs::write(profile.join("mail.db"), LEGACY_MAIL_DB).unwrap();
   153	        let (core, _) = open_fixture_core(dir.path()).unwrap();
   154	
   155	        // A reply draft written under the legacy core (same account, same IDs).
   156	        let drafts = DraftCore::open(profile.join("local-drafts")).unwrap();
   157	        let account = core.active_account().unwrap();
   158	        let detail = core.get_conversation(&conv("conv-01")).unwrap();
   159	        let source = detail.messages.last().unwrap().id.clone();
   160	        let receipt = drafts
   161	            .create_draft(
   162	                &account,
   163	                &mail_core::drafts::types::CreateDraft {
   164	                    request_id: "legacy-draft".into(),
   165	                    source: DraftSource::Reply {
   166	                        conversation: conv("conv-01"),
   167	                        source_message_id: source.clone(),
   168	                    },
   169	                    initial_content: None,
   170	                },
   171	                Some(&detail),
   172	            )
   173	            .unwrap();
   174	        let draft_files: Vec<_> = std::fs::read_dir(profile.join("local-drafts"))
   175	            .unwrap()
   176	            .map(|e| e.unwrap().file_name())
   177	            .collect();
   178	
   179	        let transition = FixtureTransition::new(&profile);
   180	        assert_eq!(
   181	            transition.status().unwrap().state,
   182	            mail_core::fixture_transition::FixtureTransitionState::NeedsDisclosure
   183	        );
   184	        let done = transition.accept().unwrap();
   185	        assert_eq!(
   186	            done.state,
   187	            mail_core::fixture_transition::FixtureTransitionState::Done
   188	        );
   189	        assert!(!profile.join("mail.db").exists());
   190	        assert_eq!(
   191	            std::fs::read_dir(profile.join("backups")).unwrap().count(),
   192	            1
   193	        );
   194	
   195	        // The core never noticed; drafts and their references are intact.
   196	        assert_eq!(core.account_status().unwrap().sync.cached_conversations, 18);
   197	        let again: Vec<_> = std::fs::read_dir(profile.join("local-drafts"))
   198	            .unwrap()
   199	            .map(|e| e.unwrap().file_name())
   200	            .collect();
   201	        assert_eq!(draft_files, again, "local-drafts untouched");
   202	        let draft = drafts.get_draft(&account, &receipt.draft_ref).unwrap();
   203	        assert_eq!(draft.revision, receipt.revision);
   204	        let reply = load_validated_reply_context(&core, &conv("conv-01"), &source).unwrap();
   205	        assert_eq!(reply.reply_context.unwrap().source_message_id, source);
   206	        core.stop();
   207	    }
   208	}
