     1	use crate::close_gate::CloseGate;
     2	use mail_core::attachments::AttachmentTransfers;
     3	use mail_core::drafts::{DraftCore, DraftService};
     4	use mail_core::gmail::sync::{GmailCore, GmailUnsubscribe};
     5	use std::sync::{Arc, Mutex};
     6	
     7	/// Managed app state retains its change-listener guard for the full app life.
     8	pub(crate) struct AppState {
     9	    pub(crate) core: GmailCore,
    10	    pub(crate) drafts: DraftService,
    11	    pub(crate) attachment_transfers: AttachmentTransfers,
    12	    pub(crate) close_gate: Arc<Mutex<CloseGate>>,
    13	    _subscription: GmailUnsubscribe,
    14	}
    15	
    16	impl AppState {
    17	    pub(crate) fn new(
    18	        core: GmailCore,
    19	        drafts: DraftCore,
    20	        on_change: impl Fn() + Send + Sync + 'static,
    21	    ) -> Self {
    22	        let subscription = core.subscribe(on_change);
    23	        Self {
    24	            drafts: DraftService::new(core.clone(), drafts),
    25	            core,
    26	            attachment_transfers: AttachmentTransfers::default(),
    27	            close_gate: Arc::new(Mutex::new(CloseGate::default())),
    28	            _subscription: subscription,
    29	        }
    30	    }
    31	}
    32	
    33	#[cfg(test)]
    34	mod tests {
    35	    use crate::state::AppState;
    36	    use crate::test_support::{conv, open};
    37	    use mail_core::drafts::DraftCore;
    38	    use mail_core::dto::{CachedDoneRequest, SetArchived};
    39	    use mail_core::error::MailError;
    40	    use mail_core::synthetic::WriteControls;
    41	    use mail_core::testing::{temp_profile, until};
    42	    use mail_core::ACCOUNT_ID;
    43	    use std::sync::mpsc;
    44	    use std::time::Duration;
    45	
    46	    #[test]
    47	    fn state_keeps_forwarding_after_command_acceptance() {
    48	        let dir = temp_profile("synthetic-events");
    49	        let core = open(dir.path(), WriteControls::default());
    50	        let (tx, rx) = mpsc::channel();
    51	        let drafts = DraftCore::open(dir.path().join("local-drafts")).unwrap();
    52	        let state = AppState::new(core, drafts, move || {
    53	            let _ = tx.send(());
    54	        });
    55	        let receipt = state
    56	            .core
    57	            .set_archived(&SetArchived {
    58	                conversation: conv("conv-01"),
    59	                archived: true,
    60	                request_id: "bridge-test".into(),
    61	            })
    62	            .unwrap();
    63	        rx.recv_timeout(Duration::from_secs(2))
    64	            .expect("acceptance event");
    65	        assert!(until(|| {
    66	            state
    67	                .core
    68	                .list_conversations()
    69	                .unwrap()
    70	                .activity
    71	                .iter()
    72	                .any(|op| {
    73	                    op.id == receipt.operation_id
    74	                        && op.status == mail_core::dto::OperationStatus::Confirmed
    75	                })
    76	        }));
    77	        // Completion also notified (drain until quiet, never sleeping).
    78	        assert!(rx.try_iter().count() >= 1 || rx.recv_timeout(Duration::from_secs(2)).is_ok());
    79	        let done = state
    80	            .core
    81	            .list_cached_done(&CachedDoneRequest {
    82	                account_id: ACCOUNT_ID.into(),
    83	                limit: 10,
    84	                cursor: None,
    85	            })
    86	            .unwrap();
    87	        assert!(done
    88	            .conversations
    89	            .iter()
    90	            .any(|row| row.conversation_ref.conversation_id == "conv-01"));
    91	        assert_eq!(done.exact_total, None);
    92	        assert_eq!(
    93	            state.core.list_cached_done(&CachedDoneRequest {
    94	                account_id: "foreign".into(),
    95	                limit: 10,
    96	                cursor: None,
    97	            }),
    98	            Err(MailError::NotFound)
    99	        );
   100	        state.core.stop();
   101	    }
   102	}
