     1	//! Secure credential custody for Gmail OAuth credentials and verified grants.
     2	//!
     3	//! Production storage is the macOS Keychain via the `keyring` crate
     4	//! (apple-native backend), holding one serialized [`TokenBundle`] under a
     5	//! single account-independent profile key so a restart can authenticate
     6	//! before account discovery. Unsupported platforms fail closed with
     7	//! [`MailError::SecretsUnavailable`]; there is no plaintext fallback.
     8	
     9	use serde::{Deserialize, Serialize};
    10	
    11	use crate::error::MailError;
    12	
    13	/// Redacted credential bundle. Serialized as JSON into the secret store;
    14	/// contents are never logged, serialized to IPC, or included in errors.
    15	#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
    16	#[serde(rename_all = "camelCase")]
    17	pub struct TokenBundle {
    18	    pub access_token: String,
    19	    /// Preserved when Google omits it in a refresh response.
    20	    pub refresh_token: Option<String>,
    21	    /// Absolute access-token expiry, epoch milliseconds.
    22	    pub expires_at_epoch_ms: i64,
    23	    /// Stable account id, set after profile discovery.
    24	    pub account_id: Option<String>,
    25	    /// Account email, set after profile discovery.
    26	    pub email: Option<String>,
    27	    /// True only after Google explicitly returned `gmail.modify` for this
    28	    /// bound account. Missing in legacy bundles and therefore denied.
    29	    #[serde(default)]
    30	    pub gmail_modify_granted: bool,
    31	}
    32	
    33	impl std::fmt::Debug for TokenBundle {
    34	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    35	        f.debug_struct("TokenBundle")
    36	            .field("access_token", &"<redacted>")
    37	            .field(
    38	                "refresh_token",
    39	                &self.refresh_token.as_ref().map(|_| "<redacted>"),
    40	            )
    41	            .field("expires_at_epoch_ms", &self.expires_at_epoch_ms)
    42	            .field(
    43	                "account_id",
    44	                &self.account_id.as_ref().map(|_| "<redacted>"),
    45	            )
    46	            .field("email", &self.email.as_ref().map(|_| "<redacted>"))
    47	            .field("gmail_modify_granted", &self.gmail_modify_granted)
    48	            .finish()
    49	    }
    50	}
    51	
    52	/// Secret store seam. Implementations must be injectable for tests; the
    53	/// production implementation is [`KeychainSecrets`].
    54	pub trait Secrets: Send + Sync {
    55	    /// Loads the stored bundle, or `None` when no credentials exist.
    56	    fn load(&self) -> Result<Option<TokenBundle>, MailError>;
    57	    /// Replaces the stored bundle.
    58	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError>;
    59	    /// Deletes the stored bundle. Disconnect must remove credentials locally.
    60	    fn clear(&self) -> Result<(), MailError>;
    61	}
    62	
    63	/// macOS Keychain credential store. Any Keychain failure fails closed:
    64	/// the caller receives [`MailError::SecretsUnavailable`], never a fallback.
    65	pub struct KeychainSecrets;
    66	
    67	#[cfg(target_os = "macos")]
    68	const SECRETS_SERVICE: &str = "mail-core-gmail";
    69	#[cfg(target_os = "macos")]
    70	const SECRETS_USER: &str = "single-profile";
    71	
    72	impl KeychainSecrets {
    73	    pub fn new() -> Self {
    74	        Self
    75	    }
    76	}
    77	
    78	impl Default for KeychainSecrets {
    79	    fn default() -> Self {
    80	        Self::new()
    81	    }
    82	}
    83	
    84	#[cfg(target_os = "macos")]
    85	impl Secrets for KeychainSecrets {
    86	    fn load(&self) -> Result<Option<TokenBundle>, MailError> {
    87	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
    88	            .map_err(|_| MailError::SecretsUnavailable)?;
    89	        match entry.get_password() {
    90	            Ok(json) => Some(
    91	                serde_json::from_str::<TokenBundle>(&json)
    92	                    .map_err(|_| MailError::SecretsUnavailable),
    93	            )
    94	            .transpose(),
    95	            Err(keyring::Error::NoEntry) => Ok(None),
    96	            Err(_) => Err(MailError::SecretsUnavailable),
    97	        }
    98	    }
    99	
   100	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError> {
   101	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
   102	            .map_err(|_| MailError::SecretsUnavailable)?;
   103	        let json = serde_json::to_string(bundle).map_err(|_| MailError::SecretsUnavailable)?;
   104	        entry
   105	            .set_password(&json)
   106	            .map_err(|_| MailError::SecretsUnavailable)
   107	    }
   108	
   109	    fn clear(&self) -> Result<(), MailError> {
   110	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
   111	            .map_err(|_| MailError::SecretsUnavailable)?;
   112	        match entry.delete_credential() {
   113	            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
   114	            Err(_) => Err(MailError::SecretsUnavailable),
   115	        }
   116	    }
   117	}
   118	
   119	#[cfg(not(target_os = "macos"))]
   120	impl Secrets for KeychainSecrets {
   121	    fn load(&self) -> Result<Option<TokenBundle>, MailError> {
   122	        Err(MailError::SecretsUnavailable)
   123	    }
   124	
   125	    fn store(&self, _bundle: &TokenBundle) -> Result<(), MailError> {
   126	        Err(MailError::SecretsUnavailable)
   127	    }
   128	
   129	    fn clear(&self) -> Result<(), MailError> {
   130	        Err(MailError::SecretsUnavailable)
   131	    }
   132	}
   133	
   134	/// In-memory secret store for synthetic tests only. It is deliberately
   135	/// exported so `crates/mail-core/tests/` can inject it, but production code
   136	/// must never select it as a fallback for [`KeychainSecrets`].
   137	#[derive(Clone, Default)]
   138	pub struct MemorySecrets {
   139	    inner: std::sync::Arc<std::sync::Mutex<MemoryState>>,
   140	}
   141	
   142	#[derive(Default)]
   143	struct MemoryState {
   144	    bundle: Option<String>,
   145	    /// Test control: when set, every operation fails closed.
   146	    unavailable: bool,
   147	}
   148	
   149	impl MemorySecrets {
   150	    pub fn new() -> Self {
   151	        Self::default()
   152	    }
   153	
   154	    /// Test-only failure injection simulating a Keychain failure.
   155	    pub fn set_unavailable(&self, unavailable: bool) {
   156	        self.inner
   157	            .lock()
   158	            .expect("memory secrets poisoned")
   159	            .unavailable = unavailable;
   160	    }
   161	}
   162	
   163	impl Secrets for MemorySecrets {
   164	    fn load(&self) -> Result<Option<TokenBundle>, MailError> {
   165	        let state = self
   166	            .inner
   167	            .lock()
   168	            .map_err(|_| MailError::SecretsUnavailable)?;
   169	        if state.unavailable {
   170	            return Err(MailError::SecretsUnavailable);
   171	        }
   172	        match &state.bundle {
   173	            None => Ok(None),
   174	            Some(json) => Some(
   175	                serde_json::from_str::<TokenBundle>(json)
   176	                    .map_err(|_| MailError::SecretsUnavailable),
   177	            )
   178	            .transpose(),
   179	        }
   180	    }
   181	
   182	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError> {
   183	        let mut state = self
   184	            .inner
   185	            .lock()
   186	            .map_err(|_| MailError::SecretsUnavailable)?;
   187	        if state.unavailable {
   188	            return Err(MailError::SecretsUnavailable);
   189	        }
   190	        let json = serde_json::to_string(bundle).map_err(|_| MailError::SecretsUnavailable)?;
   191	        state.bundle = Some(json);
   192	        Ok(())
   193	    }
   194	
   195	    fn clear(&self) -> Result<(), MailError> {
   196	        let mut state = self
   197	            .inner
   198	            .lock()
   199	            .map_err(|_| MailError::SecretsUnavailable)?;
   200	        if state.unavailable {
   201	            return Err(MailError::SecretsUnavailable);
   202	        }
   203	        state.bundle = None;
   204	        Ok(())
   205	    }
   206	}
   207	
   208	#[cfg(test)]
   209	mod tests {
   210	    use super::*;
   211	
   212	    fn bundle() -> TokenBundle {
   213	        TokenBundle {
   214	            access_token: "synthetic-access-token".to_string(),
   215	            refresh_token: Some("synthetic-refresh-token".to_string()),
   216	            expires_at_epoch_ms: 1,
   217	            account_id: None,
   218	            email: None,
   219	            gmail_modify_granted: false,
   220	        }
   221	    }
   222	
   223	    #[test]
   224	    fn token_bundle_debug_redacts_credentials_and_account_identity() {
   225	        let bundle = TokenBundle {
   226	            access_token: "synthetic-access-secret".to_string(),
   227	            refresh_token: Some("synthetic-refresh-secret".to_string()),
   228	            expires_at_epoch_ms: 123,
   229	            account_id: Some("synthetic-account-id".to_string()),
   230	            email: Some("synthetic@example.test".to_string()),
   231	            gmail_modify_granted: true,
   232	        };
   233	        let rendered = format!("{bundle:?}");
   234	        assert!(rendered.contains("<redacted>"), "{rendered}");
   235	        for secret in [
   236	            "synthetic-access-secret",
   237	            "synthetic-refresh-secret",
   238	            "synthetic-account-id",
   239	            "synthetic@example.test",
   240	        ] {
   241	            assert!(!rendered.contains(secret), "{rendered}");
   242	        }
   243	    }
   244	
   245	    #[test]
   246	    fn memory_secrets_round_trip_and_clear() {
   247	        let secrets = MemorySecrets::new();
   248	        assert_eq!(secrets.load().unwrap(), None);
   249	        secrets.store(&bundle()).unwrap();
   250	        assert_eq!(secrets.load().unwrap(), Some(bundle()));
   251	        secrets.clear().unwrap();
   252	        assert_eq!(secrets.load().unwrap(), None);
   253	        // Clearing an empty store stays idempotent.
   254	        secrets.clear().unwrap();
   255	    }
   256	
   257	    #[test]
   258	    fn memory_secrets_fail_closed_when_unavailable() {
   259	        let secrets = MemorySecrets::new();
   260	        secrets.set_unavailable(true);
   261	        assert_eq!(secrets.load(), Err(MailError::SecretsUnavailable));
   262	        assert_eq!(secrets.store(&bundle()), Err(MailError::SecretsUnavailable));
   263	        assert_eq!(secrets.clear(), Err(MailError::SecretsUnavailable));
   264	        secrets.set_unavailable(false);
   265	        assert_eq!(secrets.load().unwrap(), None);
   266	    }
   267	
   268	    /// KeychainSecrets exists on every platform but fails closed everywhere
   269	    /// except macOS; this machine is Linux, so the stub must reject.
   270	    #[cfg(not(target_os = "macos"))]
   271	    #[test]
   272	    fn keychain_secrets_fail_closed_off_macos() {
   273	        let secrets = KeychainSecrets::new();
   274	        assert_eq!(secrets.load(), Err(MailError::SecretsUnavailable));
   275	        assert_eq!(secrets.store(&bundle()), Err(MailError::SecretsUnavailable));
   276	        assert_eq!(secrets.clear(), Err(MailError::SecretsUnavailable));
   277	    }
   278	}
