  1	//! Google OAuth2 + PKCE for the desktop Gmail client.
  2	//!
  3	//! Fixed HTTPS Google endpoints, read-only by default with an explicit
  4	//! `gmail.modify` upgrade, random PKCE verifier/challenge and state, a loopback
  5	//! callback listener bound to 127.0.0.1 with exact path/state checks and a
  6	//! one-shot response, short bounded timeout, and cancellation. Tokens, codes,
  7	//! authorization URLs, subjects, addresses, and bodies are never
  8	//! debug-printed or logged.
  9	
 10	use std::collections::HashMap;
 11	use std::io::{Read, Write};
 12	use std::net::TcpListener;
 13	use std::sync::Arc;
 14	use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
 15	
 16	use base64::Engine;
 17	use rand::RngCore;
 18	use reqwest::blocking::Client;
 19	use sha2::{Digest, Sha256};
 20	use url::form_urlencoded;
 21	use url::Url;
 22	
 23	use crate::cancel::CancelToken;
 24	use crate::error::MailError;
 25	
 26	/// Scope requested by the initial read-only connection.
 27	pub const GMAIL_READONLY_SCOPE: &str = "https://www.googleapis.com/auth/gmail.readonly";
 28	/// Broader scope requested only by the explicit mailbox-actions upgrade.
 29	pub const GMAIL_MODIFY_SCOPE: &str = "https://www.googleapis.com/auth/gmail.modify";
 30	
 31	/// Bounded window for the user to finish the browser OAuth round trip.
 32	pub const AUTH_TIMEOUT: Duration = Duration::from_secs(180);
 33	
 34	/// Fixed callback path; the exact string is checked on every request.
 35	const CALLBACK_PATH: &str = "/oauth2/callback";
 36	
 37	/// Loopback accept/response poll cadence, also the cancel check cadence.
 38	const POLL_INTERVAL: Duration = Duration::from_millis(100);
 39	
 40	/// Hard cap on the callback request line + headers we will read.
 41	const MAX_REQUEST_BYTES: usize = 16 * 1024;
 42	
 43	/// Operator's Google Desktop OAuth client, loaded from the launch
 44	/// environment. The client secret (optional for desktop clients) is not
 45	/// treated as a confidential credential but is never logged or committed.
 46	#[derive(Clone)]
 47	pub struct GoogleConfig {
 48	    pub client_id: String,
 49	    pub client_secret: Option<String>,
 50	}
 51	
 52	/// Debug output redacts the client secret so an accidental `{:?}` can
 53	/// never leak it (client_id is not a confidential credential).
 54	impl std::fmt::Debug for GoogleConfig {
 55	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 56	        f.debug_struct("GoogleConfig")
 57	            .field("client_id", &self.client_id)
 58	            .field(
 59	                "client_secret",
 60	                &self.client_secret.as_ref().map(|_| "<redacted>"),
 61	            )
 62	            .finish()
 63	    }
 64	}
 65	
 66	impl GoogleConfig {
 67	    /// `EMAIL_OS_GOOGLE_CLIENT_ID` is required; missing or blank is a
 68	    /// visible `not_configured`, never a silent fallback.
 69	    /// `EMAIL_OS_GOOGLE_CLIENT_SECRET` is optional.
 70	    pub fn from_env() -> Result<Self, MailError> {
 71	        let client_id = std::env::var("EMAIL_OS_GOOGLE_CLIENT_ID")
 72	            .map_err(|_| MailError::NotConfigured)?
 73	            .trim()
 74	            .to_string();
 75	        if client_id.is_empty() {
 76	            return Err(MailError::NotConfigured);
 77	        }
 78	        let client_secret = std::env::var("EMAIL_OS_GOOGLE_CLIENT_SECRET")
 79	            .ok()
 80	            .map(|s| s.trim().to_string())
 81	            .filter(|s| !s.is_empty());
 82	        Ok(Self {
 83	            client_id,
 84	            client_secret,
 85	        })
 86	    }
 87	}
 88	
 89	/// HTTPS endpoints. Defaults are the fixed Google endpoints; tests override
 90	/// them with loopback URLs to exercise the flow without real OAuth.
 91	#[derive(Debug, Clone)]
 92	pub(crate) struct Endpoints {
 93	    pub authorize: String,
 94	    pub token: String,
 95	    pub api: String,
 96	}
 97	
 98	impl Endpoints {
 99	    pub(crate) fn google() -> Self {
100	        Self {
101	            authorize: "https://accounts.google.com/o/oauth2/v2/auth".to_string(),
102	            token: "https://oauth2.googleapis.com/token".to_string(),
103	            api: "https://gmail.googleapis.com".to_string(),
104	        }
105	    }
106	}
107	
108	/// Authorization-code grant captured from the one-shot loopback callback.
109	/// Includes the PKCE verifier because the code must be exchanged with it.
110	pub(crate) struct AuthCode {
111	    /// Never debug-printed or logged.
112	    pub code: String,
113	    pub redirect_uri: String,
114	    pub verifier: String,
115	}
116	
117	/// Debug output redacts the code and verifier so an accidental
118	/// `{:?}` can never leak authorization material.
119	impl std::fmt::Debug for AuthCode {
120	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
121	        f.debug_struct("AuthCode")
122	            .field("code", &"<redacted>")
123	            .field("redirect_uri", &"<redacted>")
124	            .field("verifier", &"<redacted>")
125	            .finish()
126	    }
127	}
128	
129	/// Token endpoint response, normalized to an absolute expiry.
130	pub(crate) struct TokenResponse {
131	    pub access_token: String,
132	    /// `None` when Google omits the refresh token; the caller preserves any
133	    /// previously stored refresh token in that case.
134	    pub refresh_token: Option<String>,
135	    /// Granted scopes, omitted by some refresh responses.
136	    pub scope: Option<String>,
137	    pub expires_at_epoch_ms: i64,
138	}
139	
140	/// Opens the authorization URL in the system browser. Test-injectable so no
141	/// real browser is launched during synthetic tests.
142	pub(crate) type UrlOpener = Arc<dyn Fn(&str) -> Result<(), MailError> + Send + Sync>;
143	
144	pub(crate) fn system_url_opener() -> UrlOpener {
145	    Arc::new(|url| webbrowser::open(url).map_err(|_| MailError::AuthFailed))
146	}
147	
148	fn now_ms() -> i64 {
149	    SystemTime::now()
150	        .duration_since(UNIX_EPOCH)
151	        .expect("system clock before epoch")
152	        .as_millis() as i64
153	}
154	
155	/// base64url alphabet without padding; every character is a valid PKCE
156	/// verifier character.
157	const PKCE_ALPHABET: &[u8] = b"REDACTED";
158	
159	fn random_b64url(len: usize) -> String {
160	    let mut rng = rand::thread_rng();
161	    let mut bytes = vec![0u8; len];
162	    rng.fill_bytes(&mut bytes);
163	    bytes
164	        .iter()
165	        .map(|b| PKCE_ALPHABET[*b as usize % PKCE_ALPHABET.len()] as char)
166	        .collect()
167	}
168	
169	/// Random PKCE verifier (64 base64url chars), its S256 challenge, and a
170	/// random state token.
171	pub(crate) struct Pkce {
172	    verifier: String,
173	    challenge: String,
174	    state: String,
175	}
176	
177	fn generate_pkce() -> Pkce {
178	    let verifier = random_b64url(64);
179	    let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD
180	        .encode(Sha256::digest(verifier.as_bytes()));
181	    let state = random_b64url(32);
182	    Pkce {
183	        verifier,
184	        challenge,
185	        state,
186	    }
187	}
188	
189	/// Starts the OAuth browser flow: bind a loopback listener on an ephemeral
190	/// port, construct the Google authorization URL (never logged), open it
191	/// externally, and wait for the one-shot callback.
192	pub(crate) fn authorize(
193	    config: &GoogleConfig,
194	    endpoints: &Endpoints,
195	    opener: &UrlOpener,
196	    scope: &str,
197	    cancel: &CancelToken,
198	    timeout: Duration,
199	) -> Result<AuthCode, MailError> {
200	    let pkce = generate_pkce();
201	    let listener = TcpListener::bind("127.0.0.1:0").map_err(|_| MailError::NetworkUnavailable)?;
202	    listener
203	        .set_nonblocking(true)
204	        .map_err(|_| MailError::NetworkUnavailable)?;
205	    let port = listener
206	        .local_addr()
207	        .map_err(|_| MailError::NetworkUnavailable)?
208	        .port();
209	    let redirect_uri = format!("http://127.0.0.1:{port}{CALLBACK_PATH}");
210	    let mut url = Url::parse(&endpoints.authorize).map_err(|_| MailError::ProviderUnavailable)?;
211	    {
212	        let mut query = url.query_pairs_mut();
213	        query.append_pair("client_id", &config.client_id);
214	        query.append_pair("redirect_uri", &redirect_uri);
215	        query.append_pair("response_type", "code");
216	        query.append_pair("scope", scope);
217	        query.append_pair("access_type", "offline");
218	        query.append_pair("prompt", "consent");
219	        query.append_pair("code_challenge", &pkce.challenge);
220	        query.append_pair("code_challenge_method", "S256");
221	        query.append_pair("state", &pkce.state);
222	    }
223	    // The URL carries PKCE/state only; it is handed to the opener, never logged.
224	    opener(url.as_ref())?;
225	    wait_for_code(
226	        &listener,
227	        &redirect_uri,
228	        &pkce.verifier,
229	        &pkce.state,
230	        timeout,
231	        cancel,
232	    )
233	}
234	
235	/// Accepts loopback connections until the exact callback path arrives with
236	/// the exact state, replies one-shot, and returns the code. Wrong paths,
237	/// wrong states, and OAuth `error` responses are rejected; cancellation and
238	/// the timeout end the wait.
239	fn wait_for_code(
240	    listener: &TcpListener,
241	    redirect_uri: &str,
242	    verifier: &str,
243	    state: &str,
244	    timeout: Duration,
245	    cancel: &CancelToken,
246	) -> Result<AuthCode, MailError> {
247	    let deadline = Instant::now() + timeout;
248	    loop {
249	        if cancel.is_cancelled() {
250	            return Err(MailError::AuthCancelled);
251	        }
252	        if Instant::now() >= deadline {
253	            return Err(MailError::AuthFailed);
254	        }
255	        match listener.accept() {
256	            Ok((mut stream, _)) => {
257	                stream
258	                    .set_read_timeout(Some(POLL_INTERVAL))
259	                    .map_err(|_| MailError::NetworkUnavailable)?;
260	                stream
261	                    .set_write_timeout(Some(Duration::from_secs(2)))
262	                    .map_err(|_| MailError::NetworkUnavailable)?;
263	                match read_request(&mut stream, deadline, cancel) {
264	                    Ok(Some(request)) => {
265	                        let target = request.split_whitespace().nth(1).unwrap_or("");
266	                        // Browsers send origin-form ("/path?query"); absolute
267	                        // form is accepted too (proxies, handcrafted GETs).
268	                        let (path, query) = if target.starts_with("http://") {
269	                            match Url::parse(target) {
270	                                Ok(parsed) => (
271	                                    parsed.path().to_string(),
272	                                    parsed.query().unwrap_or("").to_string(),
273	                                ),
274	                                Err(_) => {
275	                                    respond(&mut stream, "403 Forbidden", "Invalid callback path.");
276	                                    continue;
277	                                }
278	                            }
279	                        } else {
280	                            match target.split_once('?') {
281	                                Some((path, query)) => (path.to_string(), query.to_string()),
282	                                None => (target.to_string(), String::new()),
283	                            }
284	                        };
285	                        let params: HashMap<String, String> =
286	                            form_urlencoded::parse(query.as_bytes())
287	                                .map(|(k, v)| (k.into_owned(), v.into_owned()))
288	                                .collect();
289	                        if path != CALLBACK_PATH {
290	                            respond(&mut stream, "403 Forbidden", "Invalid callback path.");
291	                            continue;
292	                        }
293	                        if params.get("state").map(String::as_str) != Some(state) {
294	                            respond(&mut stream, "403 Forbidden", "Invalid callback.");
295	                            continue;
296	                        }
297	                        if let Some(_oauth_error) = params.get("error").filter(|e| !e.is_empty()) {
298	                            respond(&mut stream, "400 Bad Request", "Authorization failed.");
299	                            return Err(MailError::AuthFailed);
300	                        }
301	                        match params.get("code").map(String::as_str) {
302	                            Some(code) if !code.is_empty() => {
303	                                respond(
304	                                    &mut stream,
305	                                    "200 OK",
306	                                    "Authorization complete. You can close this window.",
307	                                );
308	                                return Ok(AuthCode {
309	                                    code: code.to_string(),
310	                                    redirect_uri: redirect_uri.to_string(),
311	                                    verifier: verifier.to_string(),
312	                                });
313	                            }
314	                            _ => {
315	                                respond(&mut stream, "403 Forbidden", "Invalid callback.");
316	                            }
317	                        }
318	                    }
319	                    Ok(None) => {
320	                        respond(&mut stream, "400 Bad Request", "Invalid callback request.");
321	                    }
322	                    Err(error) => return Err(error),
323	                }
324	            }
325	            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
326	                std::thread::sleep(POLL_INTERVAL);
327	            }
328	            Err(_) => return Err(MailError::NetworkUnavailable),
329	        }
330	    }
331	}
332	
333	/// Reads one bounded HTTP request, polling cancellation and the shared OAuth
334	/// deadline between socket reads so a trickling peer cannot hold sign-in open.
335	fn read_request(
336	    stream: &mut std::net::TcpStream,
337	    deadline: Instant,
338	    cancel: &CancelToken,
339	) -> Result<Option<String>, MailError> {
340	    let mut buf = Vec::new();
341	    let mut chunk = [0u8; 1024];
342	    loop {
343	        if cancel.is_cancelled() {
344	            return Err(MailError::AuthCancelled);
345	        }
346	        if Instant::now() >= deadline {
347	            return Err(MailError::AuthFailed);
348	        }
349	        if buf.windows(4).any(|w| w == b"\r\n\r\n") || buf.len() >= MAX_REQUEST_BYTES {
350	            break;
351	        }
352	        match stream.read(&mut chunk) {
353	            Ok(0) => break,
354	            Ok(n) => buf.extend_from_slice(&chunk[..n]),
355	            Err(error)
356	                if matches!(
357	                    error.kind(),
358	                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
359	                ) => {}
360	            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
361	            Err(_) => break,
362	        }
363	    }
