//! The native command manifest: every source that names a command must agree
//! with the `generate_handler!` list in `lib.rs`.

use std::{collections::BTreeSet, fs};

fn quoted_values(source: &str, marker: &str) -> BTreeSet<String> {
    source
        .lines()
        .filter_map(|line| {
            let value = if marker == "\"" {
                line.trim()
            } else {
                line.split_once(marker)?.1.trim()
            };
            let value = value.trim();
            let value = value.strip_prefix('"')?.split('"').next()?;
            Some(value.to_owned())
        })
        .collect()
}

fn assert_command_sets_match(expected: &BTreeSet<String>, actual: &BTreeSet<String>, source: &str) {
    let missing: Vec<_> = expected.difference(actual).collect();
    let extra: Vec<_> = actual.difference(expected).collect();
    assert!(
        missing.is_empty() && extra.is_empty(),
        "{source} differs from generate_handler!: missing {missing:?}; extra {extra:?}"
    );
}

#[test]
fn native_command_manifests_match_across_all_sources() {
    let main = include_str!("lib.rs");
