import { ref } from 'vue';
import type { MailClient } from '../lib/ipc/client';
import { errorText } from '../lib/error-text';
import { reloadPage } from '../lib/reload';

export const CONNECT_AFTER_SWITCH_KEY = 'email-os.connect-after-switch';
export function takeConnectAfterSwitch(): boolean {
  try {
    const value = sessionStorage.getItem(CONNECT_AFTER_SWITCH_KEY);
    sessionStorage.removeItem(CONNECT_AFTER_SWITCH_KEY);
    return value === 'true';
  } catch { return false; }
}

export function useModeChoice(client: MailClient) {
  const phase = ref<'checking' | 'choose' | 'switching' | 'clear'>('checking');
  const error = ref<string | null>(null);
  const fail = (e: unknown) => {
    error.value = errorText(e && typeof e === 'object' && 'kind' in e ? e as { kind: string } : { kind: 'unknown' });
    phase.value = 'choose';
  };
  async function load() {
    phase.value = 'checking'; error.value = null;
    try { phase.value = (await client.getModeChoice()).chosen ? 'clear' : 'choose'; } catch (e) { fail(e); }
  }
  async function chooseDemo() {
    if (phase.value !== 'choose') return;
    phase.value = 'switching'; error.value = null;
    try {
      const result = await client.switchMode('fixture');
      if (result.mode === 'fixture') phase.value = 'clear'; else reloadPage();
    } catch (e) { fail(e); }
  }
  async function chooseOwnMail() {
    if (phase.value !== 'choose') return;
    phase.value = 'switching'; error.value = null;
    try { sessionStorage.setItem(CONNECT_AFTER_SWITCH_KEY, 'true'); } catch { /* Storage is optional. */ }
    try { await client.switchMode('gmail'); reloadPage(); } catch (e) {
      try { sessionStorage.removeItem(CONNECT_AFTER_SWITCH_KEY); } catch { /* Storage is optional. */ }
      fail(e);
    }
  }
  return { phase, error, load, chooseDemo, chooseOwnMail };
}
